 * @param {number} duracionMs - Tiempo que tardó en ejecutarse (en ms)
 * @returns {Promise<void>}
 */
async function recordMigration(db, nombre, duracionMs) {
    try {
        await db.run(
            'INSERT INTO migrations (nombre, duracion_ms) VALUES (?, ?)',
            [nombre, duracionMs]
        );
    } catch (error) {
